def bbox(oid,xywh,coordinate='overview1200'):
 if coordinate=='original':return xywh
 return [round(v*full[oid]['width']/1200) for v in xywh]
def ref(oid,box,part,coordinate='overview1200'):
 a=full[oid];return {'oid':oid,'manifest_label':a['canvas_label'],'source_url':a['url'],'full_image_sha256':a['sha256'],'full_image_size':[a['width'],a['height']],'object_region_xywh':bbox(oid,box,coordinate),'region_description':part}
R=[]
def add(fid,so,sb,to,tb,part,sim,diff,decision,why,scoord='overview1200',tcoord='overview1200',text='A short writing area is nearby; no explicit text-to-object leader was observed. Source annotation supplies the candidate locator, not independently proven semantic attachment.',extras=None):
 original=next(x for x in roster if x['fragment_id']==fid)
 r={'pair_id':original['pair_id'],'fragment_id':fid,'source_folio':original['pharma_folio'],'target_folio':original['herbal_folio'],'prior_hypothesis':{'source_url':original['illustration_source_url'],'author':original['source_pair']['author'],'grade':original['source_grade'],'interpretation':'Prior apparent correspondence hypothesis' if original['source_grade']=='A' else 'Prior tentative visual resemblance hypothesis','semantic_gold':False},'source_number_table':{'row_top_to_bottom':original['source_pair']['row_top_to_bottom'],'column':original['source_pair']['column_in_source_number_table'],'method':'Source author number table plus unnumbered source scan overview checked against Yale canvas. Numbers are not printed in the downloaded overview.'},'candidate_locators':original['candidate_locators'],'source':ref(so,sb,part,scoord),'target':ref(to,tb,'Whole target drawing or relevant visible region as specified in comparison',tcoord),'comparison_scope':part,'visible_similarities':sim,'visible_differences_and_missing_evidence':diff,'object_localization':'located_at_coarse_object_level','comparison_decision':decision,'decision_reason':why,'same_historical_plant':'uncertain','species_identification':None,'text_geometry':text,'lexical_scores_read':False,'failed':False}
 if extras:r.update(extras)
 R.append(r)
S='suitable_for_partial_shape_comparison';L='limited_or_ambiguous'
add(212,'1006251',[5280,2470,1540,960],'1006109',[850,2600,1740,1080],'Root-shaped portion only; aerial parts not present in fragment', ['Both have an elongated horizontal brown body with repeated upward and downward projections.','Both have an upright hollow/intertwined-looking neck near one end and a long recurved continuation beneath the horizontal body.'],['The source is smaller, compressed, and damaged/folded nearby; counts and proportions of projections differ.','The target includes many green lobed leaves and a large terminal form, entirely absent from this root fragment.'],S,'Distinctive coarse root architecture can be compared; identity of the whole plant cannot be established.',scoord='original',tcoord='original',extras={'dependency_note':'Shares source folio/physical leaf f102 with fragments 213,225,240. Prior source also notes target f18v/f23r bifolio association; this audit did not independently reconstruct binding.'})
add(213,'1006251',[6840,2730,1180,740],'1006118',[350,2890,2090,600],'Root/rhizome-shaped horizontal portion only', ['Both show a long approximately horizontal cylinder with repeated rounded or oval node/cut-like outlines and downward thin offshoots.'],['Source paint and ink are faint and crossed by a fold; details of individual nodes are not equally visible.','Target has two tall leafy shoots and blue terminal forms; the source fragment supplies none of these.','Target node outlines are larger and more regular; the source is more compressed.'],S,'Enough distinctive geometry for a partial root comparison, with preservation limits.',scoord='original',tcoord='original',extras={'dependency_note':'Same source folio/leaf as 212,225,240; do not call these independent confirmations.'})
add(240,'1006253',[510,770,315,300],'1006110',[200,280,880,1300],'Small root plus one drooping comb-like leaf; compare target lower portion', ['Both have a thick ochre central root neck opening into several curved root branches.','Both include a bowed green leaf shape with long hanging finger/comb-like divisions.'],['Source has one such hanging leaf at the upper right; target has two much larger lower fronds.','Target adds a tall central stem, small narrow leaves, clustered side terminals and a blue top form; these are absent in the source fragment.','Root branch count and crossing details differ.'],S,'Root and leaf-shape overlap supports partial comparison; not a full-plant match.',extras={'dependency_note':'Source f102 physical leaf shared with 212,213,225.'})
add(80,'1006246',[230,480,90,175],'1006174',[510,1080,520,490],'Tiny crossed two-part root; target root only', ['Two descending root-like ribbons cross to form a narrow loop and then separate into tapered ends.'],['The source is tiny and rounded at its upper end; target root is much thicker, longer and more strongly filled red-brown.','No target flowers or unusual projecting leaf margins appear in the source.','Crossing two tapered lobes is a low-specificity feature.'],L,'Object is localized, but generic root silhouette alone provides weak identification evidence.',extras={'dependency_note':'Shares source leaf f99 with 94,95,110.'})
add(94,'1006246',[260,1020,900,575],'1006245',[400,150,780,1370],'Bent root attached to long stem with angular leaves and small red terminal clusters', ['Both have green angular/triangular leaf silhouettes with basal notches.','Both include small red clustered terminal marks on drooping portions and a thick brown root.'],['Source lies largely sideways, with a long horizontally banded root and few leaves; target is upright with numerous leaves on two long hanging branches.','Target root is a compact bent taper with fine offshoots; source root has repeated broad oblique paint bands and a more elongated body.','Number and arrangement of red terminal clusters differ.'],S,'Several coarse visible features can be compared, while overall arrangement differs.',extras={'dependency_note':'Target f96v is reused by fragment116; that reuse is not independent target evidence. Source leaf f99 shared with80,95,110.'})
add(95,'1006247',[275,55,130,245],'1006160',[200,730,730,800],'Long narrow reddish root-like axis with many lateral projections', ['Both have a reddish elongated main axis with many thin lateral hooked/tapered offshoots.'],['Source is short and almost vertical with a strongly painted centre; target has a long bent lower axis and more fine striated outlines.','Target fan of broad green/blue leaves and top terminal shape are absent.','Many other fragments use branching/tapered roots, so this similarity is not very specific.'],L,'Root-only comparison is possible, but the available shape is too generic for secure object identity.',extras={'dependency_note':'Shares f99 source leaf with80,94,110.'})
add(110,'1006247',[1030,1620,440,540],'1006141',[200,1030,970,510],'One hooked horizontal root-like fragment; target lower branching root only', ['Source and target both have a thick horizontal root-like section with downturned tapered branches.','A vertical attachment rises from the thick portion in each.'],['Source is a single curved lobe with few short branches; target is a much larger branching root system extending both left and right with multiple connections.','Target has rows of rounded leaf-like disks and several upper terminals, absent in the source.','No unique subsegment mapping from the small hook to the complex target is demonstrable.'],L,'One source object can be localized, but the precise counterpart within the target root remains uncertain.',scoord='original',text='Two supplied candidate text loci belong to this one numbered source hypothesis. Visible writing above/near the hooked root has no leader lines tying separate strings to distinct components; no glyphs were transcribed. Do not split it into two independent object matches.',extras={'dependency_note':'One grouped hypothesis with candidate locators f99v.27 and f99v.28, not two tests. Same source leaf f99 as80,94,95.','grouped_source_object_count':1,'target_subsegment_uncertain':True})
add(116,'1006248',[280,90,200,230],'1006245',[400,150,780,1370],'Small coiled stem with sparse triangular green leaves', ['Both include several green triangular/arrow-like leaves attached by short stalks.'],['Source main stem curls into a prominent loop; target has an upright central stem and two long downward branches.','Source lacks the target red clusters and its substantial root architecture.','Source leaves are few and small; target leaf series is long and differently arranged.'],L,'Leaf-outline comparison is possible, but the overall structure and missing parts make identity weak.',extras={'dependency_note':'Target f96v is also used by94; source f100 shares a physical leaf with133 and136.'})
add(133,'1006249',[1740,170,510,680],'1006099',[500,240,590,1320],'Compact green curled/rounded leaf cluster and small root', ['Both use overlapping rounded or crescent-like green leaf units; several curl inward near their attachment.'],['Source has multiple separately outlined curled units along thin stalks; target has dense layered crescent bands in large discrete clusters.','Target uses alternating green/ochre patches and blue terminal forms; source cluster is largely green and lacks comparable terminal forms.','Root shape and relative scale differ.'],L,'Candidate object is clear, but overlap is mainly a broad drawing motif; exact target-part equivalence is uncertain.',scoord='original',extras={'dependency_note':'Shares f100 source leaf with116 and136.'})
add(136,'1006249',[1050,810,590,760],'1006236',[300,60,820,1530],'Branching stem bearing many narrow green leaflets', ['Both show repeated narrow elongated green leaflets arranged along several lateral branches.','The branching leafy spray is more comparable than the root portion.'],['Source is a compact leaf spray with a thin, faint root; target is tall and has a broad root fan.','Target has three large pale terminal forms; source does not.','Leaf spacing, branch count and proportions differ.'],S,'Leaf arrangement supports partial comparison under the documented working canvas identification.',scoord='original',extras={'dependency_note':'Same f100 source leaf as116 and133.','canvas_conflict':{'working_target_folio':'f90v2','official_manifest_label':full['1006236']['canvas_label'],'oid':'1006236','resolution':'Parent supplied source-link plus three-canvas visual correspondence; this observer confirms visible three pale terminal forms, narrow leaflets and two lower text blocks on supplied canvas.','historical_recto_verso_adjudicated':False}})
add(225,'1006252',[710,330,155,150],'1006144',[260,300,740,1270],'Single small green lobed leaf/fragment on a narrow stalk', ['Both include deeply indented green leaf silhouettes with rounded subsidiary lobes arranged around a centre.'],['Source is one small curled outline; target bears many larger multi-armed leaf units with deeper divisions.','Target flowers, long stems and root system have no counterpart in the fragment.','Some target parts are darkened/damaged, limiting outline comparison.'],L,'A coarse leaf-outline comparison is feasible, but very little object information overlaps.',extras={'dependency_note':'Shares f102 source physical leaf with212,213,240.'})
add(61,'1006234',[800,690,340,340],'1006168',[120,320,680,1030],'Small rooted plant with few green fingered leaf units', ['Both include green units with a rounded body and several narrow finger-like extensions at one end.','Both show these units attached by thin stems to a central branching structure.'],['Source has very few painted units and a thick ochre branching root; target has many repeated green units and lightly drawn fine roots.','Target upper pale rounded terminal forms are absent from the small source.','Scale, number of units and root outline differ.'],S,'Recognizable leaf-shape overlap permits partial object comparison, not species identification.')
